(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const BLUE = '#36d9ff', ORANGE = '#ff814b';
  const FIELD = { w: 1000, h: 620, goalW: 190 };
  const keys = new Set();
  let W = 0, H = 0, dpr = 1, scale = 1, ox = 0, oy = 0;
  let state = 'menu', last = 0, timeLeft = 300, kickoff = 0, shake = 0, soundOn = true, audio;
  let blueScore = 0, orangeScore = 0, boost = 100, goalTimer = 0, toastTimer = 0;
  const cars = [], particles = [], pads = [];
  const ball = { x: 500, y: 310, vx: 0, vy: 0, z: 0, vz: 0, r: 18, spin: 0 };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const hypot = Math.hypot;
  function resize() {
    W = innerWidth; H = innerHeight; dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
    scale = Math.min((W - 28) / FIELD.w, (H - 20) / FIELD.h);
    ox = (W - FIELD.w * scale) / 2; oy = (H - FIELD.h * scale) / 2;
  }
  addEventListener('resize', resize); resize();
  function makeCar(team, x, y, angle, human = false, role = 0) {
    return { team, x, y, vx: 0, vy: 0, angle, speed: 0, boost: human ? 100 : 75, human, role,
      z: 0, vz: 0, jumpCooldown: 0, hitFlash: 0, trail: [], aiBoost: 0, lastTouch: 0 };
  }
  function initPads() {
    pads.length = 0;
    for (const x of [180, 320, 500, 680, 820]) for (const y of [125, 495]) pads.push({x,y,amount: x===500?24:12, cooldown:0, phase:Math.random()*6});
    for (const x of [90, 910]) for (const y of [205, 415]) pads.push({x,y,amount:12,cooldown:0,phase:Math.random()*6});
  }
  function resetCars() {
    cars.length = 0;
    cars.push(makeCar('blue',500,518,-Math.PI/2,true));
    cars.push(makeCar('blue',310,548,-Math.PI/2,false,1), makeCar('blue',690,548,-Math.PI/2,false,2));
    cars.push(makeCar('orange',500,102,Math.PI/2,false,0), makeCar('orange',310,72,Math.PI/2,false,1), makeCar('orange',690,72,Math.PI/2,false,2));
    ball.x=500;ball.y=310;ball.vx=ball.vy=ball.z=ball.vz=0;ball.spin=0;
    boost=100;kickoff=2.2;
    for(const p of pads)p.cooldown=0;
  }
  initPads(); resetCars();
  function startMatch() { blueScore=orangeScore=0;timeLeft=300; $('blueScore').textContent='0';$('orangeScore').textContent='0';$('startOverlay').classList.add('hidden');$('resultOverlay').classList.add('hidden');state='playing';resetCars();notify('KICKOFF IN 3'); }
  function togglePause(force) {
    if(state==='menu'||state==='finished') return;
    const pause = force ?? state==='playing';
    if(pause&&state==='playing'){state='paused';$('pauseOverlay').classList.remove('hidden');}
    else if(!pause&&state==='paused'){state='playing';$('pauseOverlay').classList.add('hidden');last=performance.now();}
  }
  function notify(text) {const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=1.4;}
  function sound(freq=420,duration=.08,type='sine',volume=.035) {
    if(!soundOn) return;
    try { audio ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration); } catch {}
  }
  function direction(team) { return team==='blue' ? -1 : 1; }
  function targetFor(car) {
    const attack = direction(car.team), b=ball;
    let tx=b.x, ty=b.y - attack*52;
    if(car.role===1){tx=clamp(b.x-115,100,900);ty=b.y-attack*36;}
    if(car.role===2){tx=clamp(b.x+115,100,900);ty=b.y-attack*36;}
    if(car.role===0 && ((car.team==='blue'&&b.y>450)||(car.team==='orange'&&b.y<170))){tx=500;ty=car.team==='blue'?500:120;}
    // Approach behind the ball to drive it toward the opposing goal.
    return {x:clamp(tx,70,930),y:clamp(ty,45,575)};
  }
  function controlsFor(car) {
    if(car.human) {
      return {throttle:(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0), steer:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0), boost:keys.has('shift')||keys.has(' ')};
    }
    const t=targetFor(car), dx=t.x-car.x,dy=t.y-car.y,desired=Math.atan2(dy,dx)+Math.PI/2;
    const err=Math.atan2(Math.sin(desired-car.angle),Math.cos(desired-car.angle));
    const dist=hypot(dx,dy);let throttle=dist>45?1:.25;
    if(Math.abs(err)>2.35)throttle=-.5;
    const boostAI=dist>185&&Math.abs(err)<.28&&car.boost>20;
    return {throttle,steer:clamp(err*2.7,-1,1),boost:boostAI};
  }
  function jump(car) { if(car.jumpCooldown<=0 && car.z<1){car.vz=310;car.jumpCooldown=.38;sound(180,.1,'triangle',.022);} }
  function emit(x,y,color,count=7,power=1) {
    for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(35+Math.random()*180)*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.55,max:.9,size:2+Math.random()*5,color});}
  }
  function hitBall(car,dt) {
    const dx=ball.x-car.x,dy=ball.y-car.y,d=hypot(dx,dy),reach=ball.r+27+(car.z>0?car.z*.22:0);
    if(d>=reach||d<.01)return;
    const nx=dx/d,ny=dy/d,closing=(car.vx-ball.vx)*nx+(car.vy-ball.vy)*ny;
    const impulse=Math.max(95,closing*.9+135+(car.human&&keys.has('shift')?110:0));
    ball.vx+=nx*impulse+car.vx*.12;ball.vy+=ny*impulse+car.vy*.12;
    if(car.z>12){ball.vz=Math.max(ball.vz,car.vz*.55+95);}
    const overlap=reach-d;ball.x+=nx*overlap;ball.y+=ny*overlap;
    if(car.hitFlash<=0){car.hitFlash=.14;emit(ball.x,ball.y,car.team==='blue'?BLUE:ORANGE,4,.55);sound(145+Math.random()*100,.06,'triangle',.018);}
    car.lastTouch=performance.now();
  }
  function goal(team) {
    if(team==='blue'){blueScore++;$('blueScore').textContent=blueScore;}else{orangeScore++;$('orangeScore').textContent=orangeScore;}
    state='goal';goalTimer=2.1;shake=13;emit(ball.x,ball.y,team==='blue'?BLUE:ORANGE,70,1.8);
    $('goalFlash').classList.remove('animate');void $('goalFlash').offsetWidth;$('goalFlash').classList.add('animate');
    notify(team==='blue'?'BLUE TEAM SCORES!':'ORANGE TEAM SCORES!');sound(610,.28,'sawtooth',.06);setTimeout(()=>sound(850,.38,'sine',.04),120);
  }
  function finish() {
    state='finished';$('pauseOverlay').classList.add('hidden');$('resultOverlay').classList.remove('hidden');
    const win=blueScore>orangeScore; $('resultTitle').innerHTML=win?'VICTORY<br><span>IS YOURS.</span>':blueScore===orangeScore?'DEAD<br><span>EVEN.</span>':'NICE<br><span>TRY.</span>';
    $('resultCopy').textContent=`FINAL SCORE  ${blueScore} — ${orangeScore}. ${win?'The arena won’t forget that one.':blueScore===orangeScore?'Neither team could be separated.':'The rematch is calling.'}`;
  }
  function update(dt) {
    if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show');}
    if(state==='goal'){goalTimer-=dt;if(goalTimer<=0){if(blueScore>=5||orangeScore>=5){finish();return;}state='playing';resetCars();notify('KICKOFF!');}return;}
    if(state!=='playing')return;
    if(kickoff>0){kickoff-=dt;if(kickoff<0)kickoff=0;}
    else timeLeft=Math.max(0,timeLeft-dt);
    if(timeLeft<=0){finish();return;}
    const mins=Math.floor(timeLeft/60),secs=Math.floor(timeLeft%60);$('clock').textContent=`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;
    const p=cars[0],pc=controlsFor(p);
    if(pc.boost&&boost>0&&Math.abs(pc.throttle)+Math.abs(pc.steer)>0){boost=Math.max(0,boost-32*dt);}
    else boost=Math.min(100,boost+10*dt);
    $('boostNumber').textContent=Math.round(boost);$('boostFill').style.width=boost+'%';
    if(keys.has('q')||keys.has('e')){if(!p.jumpHeld){jump(p);p.jumpHeld=true;}}else p.jumpHeld=false;
    for(const car of cars){
      const c=car===p?pc:controlsFor(car);car.jumpCooldown=Math.max(0,car.jumpCooldown-dt);car.hitFlash=Math.max(0,car.hitFlash-dt);
      if(!car.human&&car.z===0&&Math.random()<dt*.22&&hypot(ball.x-car.x,ball.y-car.y)<95)jump(car);
      const speed=hypot(car.vx,car.vy),turn=2.45*(.26+Math.min(speed,260)/260);
      car.angle+=c.steer*turn*dt*(c.throttle<-.1?-1:1);
      let accel=c.throttle*390*(car.z>0?.76:1);
      const wantBoost=c.boost&&(car.human?boost>0:car.boost>0);
      if(wantBoost&&Math.abs(c.throttle)+Math.abs(c.steer)>.1){accel+=Math.max(0,c.throttle)*450;if(!car.human)car.boost=Math.max(0,car.boost-24*dt);}
      car.vx+=Math.sin(car.angle)*accel*dt;car.vy-=Math.cos(car.angle)*accel*dt;
      const drag=Math.pow(car.z>0?.989:.976,dt*60);car.vx*=drag;car.vy*=drag;
      const cap=wantBoost?440:300,sp=hypot(car.vx,car.vy);if(sp>cap){car.vx*=cap/sp;car.vy*=cap/sp;}
      car.x+=car.vx*dt;car.y+=car.vy*dt;
      if(car.x<28||car.x>972){car.x=clamp(car.x,28,972);car.vx*=-.42;}
      if(car.y<28||car.y>592){car.y=clamp(car.y,28,592);car.vy*=-.42;}
      car.z+=car.vz*dt;car.vz-=690*dt;if(car.z<0){car.z=0;car.vz=0;}
      if(wantBoost&&speed>110&&Math.random()<dt*45){const bx=car.x-Math.sin(car.angle)*22,by=car.y+Math.cos(car.angle)*22;emit(bx,by,car.team==='blue'?BLUE:ORANGE,1,.25);}
      hitBall(car,dt);
    }
    // Gentle vehicle-to-vehicle bumping keeps traffic dynamic without trapping cars.
    for(let i=0;i<cars.length;i++)for(let j=i+1;j<cars.length;j++){const a=cars[i],b=cars[j],dx=b.x-a.x,dy=b.y-a.y,d=hypot(dx,dy);if(d>0&&d<34){const push=(34-d)*.5,nx=dx/d,ny=dy/d;a.x-=nx*push;a.y-=ny*push;b.x+=nx*push;b.y+=ny*push;a.vx-=nx*push*2;b.vx+=nx*push*2;a.vy-=ny*push*2;b.vy+=ny*push*2;}}
    // Ball flight and arena rebound.
    ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;ball.vx*=Math.pow(.992,dt*60);ball.vy*=Math.pow(.992,dt*60);ball.spin+=hypot(ball.vx,ball.vy)*dt*.025;
    ball.z+=ball.vz*dt;ball.vz-=540*dt;if(ball.z<0){ball.z=0;if(Math.abs(ball.vz)>65)ball.vz*=-.42;else ball.vz=0;ball.vx*=.985;ball.vy*=.985;}
    const inGoal=Math.abs(ball.x-500)<FIELD.goalW/2-4;
    if(inGoal&&ball.y<-ball.r-5){goal('blue');return;}if(inGoal&&ball.y>FIELD.h+ball.r+5){goal('orange');return;}
    if(ball.x<ball.r+16){ball.x=ball.r+16;ball.vx=Math.abs(ball.vx)*.75;}if(ball.x>FIELD.w-ball.r-16){ball.x=FIELD.w-ball.r-16;ball.vx=-Math.abs(ball.vx)*.75;}
    if(ball.y<ball.r+15&&!inGoal){ball.y=ball.r+15;ball.vy=Math.abs(ball.vy)*.73;}if(ball.y>FIELD.h-ball.r-15&&!inGoal){ball.y=FIELD.h-ball.r-15;ball.vy=-Math.abs(ball.vy)*.73;}
    for(const pad of pads){pad.cooldown=Math.max(0,pad.cooldown-dt);if(pad.cooldown<=0){for(const car of cars){if(hypot(car.x-pad.x,car.y-pad.y)<23){pad.cooldown=5;emit(pad.x,pad.y,'#b4ff71',8,.65);if(car.human)boost=Math.min(100,boost+pad.amount);else car.boost=Math.min(100,car.boost+pad.amount);sound(720,.09,'sine',.025);break;}}}}
    for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.life-=dt;if(a.life<=0){particles.splice(i,1);continue;}a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=.97;a.vy*=.97;}
    shake=Math.max(0,shake-dt*28);
  }

function rounded(x,y,w,h,r,fill,stroke,line=1){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.lineWidth=line;ctx.strokeStyle=stroke;ctx.stroke();}}
function drawGoal(y,team) {
  const color=team==='blue'?BLUE:ORANGE, top=y===0;
  const gy=top?-58:FIELD.h+58;
  ctx.save();ctx.translate(500,gy);
  ctx.fillStyle=team==='blue'?'#0c4964':'#62351f';ctx.globalAlpha=.88;ctx.fillRect(-FIELD.goalW/2,-55,FIELD.goalW,110);ctx.globalAlpha=1;
  ctx.strokeStyle=color+'77';ctx.lineWidth=1;
  for(let i=-FIELD.goalW/2;i<=FIELD.goalW/2;i+=19){ctx.beginPath();ctx.moveTo(i,-55);ctx.lineTo(i,55);ctx.stroke();}
  for(let j=-55;j<=55;j+=17){ctx.beginPath();ctx.moveTo(-FIELD.goalW/2,j);ctx.lineTo(FIELD.goalW/2,j);ctx.stroke();}
  ctx.shadowColor=color;ctx.shadowBlur=18;ctx.strokeStyle=color;ctx.lineWidth=7;ctx.strokeRect(-FIELD.goalW/2,-55,FIELD.goalW,110);ctx.shadowBlur=0;
  ctx.fillStyle=color;ctx.font='800 16px Barlow Condensed, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(team==='blue'?'BLUE END':'ORANGE END',0,top?37:-37);ctx.restore();
}
function drawField(now) {
  const grad=ctx.createLinearGradient(0,0,FIELD.w,FIELD.h);grad.addColorStop(0,'#173846');grad.addColorStop(.48,'#12313e');grad.addColorStop(1,'#172e3c');
  rounded(0,0,FIELD.w,FIELD.h,26,'#081622','#628091',8);
  ctx.save();ctx.beginPath();ctx.roundRect(8,8,FIELD.w-16,FIELD.h-16,22);ctx.clip();ctx.fillStyle=grad;ctx.fillRect(0,0,FIELD.w,FIELD.h);
  // Long alternating turf lanes.
  for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#ffffff03':'#00131b0d';ctx.fillRect(i*100,8,100,FIELD.h-16);}
  ctx.fillStyle='rgba(25,190,224,.055)';ctx.fillRect(10,10,FIELD.w-20,FIELD.h/2-10);ctx.fillStyle='rgba(255,132,72,.045)';ctx.fillRect(10,FIELD.h/2,FIELD.w-20,FIELD.h/2-10);
  // Subtle synthetic turf texture and light rays.
  ctx.strokeStyle='#d5faff08';ctx.lineWidth=1;for(let x=28;x<FIELD.w;x+=25){ctx.beginPath();ctx.moveTo(x,18);ctx.lineTo(x+Math.sin(x)*5,FIELD.h-18);ctx.stroke();}
  const line='#d8f3f442';ctx.strokeStyle=line;ctx.lineWidth=2;ctx.strokeRect(20,20,FIELD.w-40,FIELD.h-40);
  ctx.beginPath();ctx.moveTo(20,FIELD.h/2);ctx.lineTo(980,FIELD.h/2);ctx.stroke();
  ctx.beginPath();ctx.arc(500,310,82,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(500,310,5,0,Math.PI*2);ctx.fillStyle='#d8f3f4aa';ctx.fill();
  // Box markings and the goal mouths.
  ctx.strokeStyle='#d8f3f43a';ctx.lineWidth=2;ctx.strokeRect(365,20,270,92);ctx.strokeRect(405,20,190,47);ctx.strokeRect(365,508,270,92);ctx.strokeRect(405,553,190,47);
  ctx.strokeStyle='#36d9ff99';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(405,20);ctx.lineTo(595,20);ctx.stroke();ctx.strokeStyle='#ff814b99';ctx.beginPath();ctx.moveTo(405,600);ctx.lineTo(595,600);ctx.stroke();
  // Side-wall segmented light bars.
  for(let x=35;x<965;x+=36){ctx.fillStyle=x<500?'#42dfff25':'#ff955025';ctx.fillRect(x,12,16,3);ctx.fillRect(x,605,16,3);}
  // Boost pads pulse in and out.
  for(const p of pads){const active=p.cooldown<=0,r=active?8+Math.sin(now*.004+p.phase)*1.5:5;ctx.save();ctx.globalAlpha=active?1:.27;ctx.shadowColor='#adff63';ctx.shadowBlur=active?16:0;ctx.fillStyle=active?'#c5ff76':'#8cae67';ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#e2ffc5';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(p.x,p.y,r*.45,0,Math.PI*2);ctx.stroke();ctx.restore();}
  ctx.restore();
  // Decorative outer rails and luminous corner pylons.
  rounded(-4,-4,FIELD.w+8,FIELD.h+8,28,null,'#ffffff2a',2);
  for(const [x,y,c] of [[10,10,BLUE],[990,10,BLUE],[10,610,ORANGE],[990,610,ORANGE]]){ctx.save();ctx.shadowColor=c;ctx.shadowBlur=14;ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.restore();}
}
function drawCar(car,now) {
  const color=car.team==='blue'?BLUE:ORANGE, dark=car.team==='blue'?'#0879a4':'#b7461e';
  const lift=car.z*.55;
  // Ground shadow remains on the pitch while a car is airborne.
  ctx.save();ctx.translate(car.x,car.y);ctx.globalAlpha=Math.max(.15,.38-car.z/900);ctx.fillStyle='#020912';ctx.beginPath();ctx.ellipse(0,9,24+car.z*.04,13+car.z*.03,0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.save();ctx.translate(car.x,car.y-lift);ctx.rotate(car.angle+Math.PI/2);
  if(car.human){ctx.save();ctx.globalAlpha=.75+Math.sin(now*.006)*.15;ctx.strokeStyle='#d9faff';ctx.lineWidth=1.5;ctx.setLineDash([3,5]);ctx.beginPath();ctx.ellipse(0,0,31,24,0,0,Math.PI*2);ctx.stroke();ctx.restore();}
  // Wheels.
  ctx.fillStyle='#07111a';for(const x of [-15,15])for(const y of [-12,11]){rounded(x-4,y-6,8,13,3,'#050b12','#8ca7b4',1);ctx.fillStyle='#9fbac6';ctx.fillRect(x-1,y-4,2,8);ctx.fillStyle='#07111a';}
  // Rocket chassis, bumpers and hood.
  ctx.shadowColor=color;ctx.shadowBlur=car.human?12:7;
  ctx.beginPath();ctx.moveTo(-12,19);ctx.lineTo(-17,11);ctx.lineTo(-15,-9);ctx.lineTo(-10,-19);ctx.lineTo(-6,-23);ctx.lineTo(6,-23);ctx.lineTo(10,-19);ctx.lineTo(15,-9);ctx.lineTo(17,11);ctx.lineTo(12,19);ctx.closePath();
  const body=ctx.createLinearGradient(-18,-16,16,17);body.addColorStop(0,car.human?'#aaf4ff':color);body.addColorStop(.35,color);body.addColorStop(1,dark);ctx.fillStyle=body;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#e7fbffb0';ctx.lineWidth=1;ctx.stroke();
  // Windshield and rear glass.
  ctx.beginPath();ctx.moveTo(-8,-15);ctx.lineTo(-5,-19);ctx.lineTo(5,-19);ctx.lineTo(8,-15);ctx.lineTo(7,-7);ctx.lineTo(-7,-7);ctx.closePath();ctx.fillStyle='#102536';ctx.fill();ctx.strokeStyle='#e3faff8a';ctx.stroke();
  ctx.beginPath();ctx.moveTo(-7,1);ctx.lineTo(7,1);ctx.lineTo(9,9);ctx.lineTo(-9,9);ctx.closePath();ctx.fillStyle='#142a38';ctx.fill();
  ctx.fillStyle='#f0ffff';ctx.globalAlpha=.9;ctx.fillRect(-11,-21,4,2);ctx.fillRect(7,-21,4,2);ctx.globalAlpha=1;
  ctx.fillStyle=car.team==='blue'?'#76efff':'#ffc08e';ctx.fillRect(-12,16,7,2);ctx.fillRect(5,16,7,2);
  if(car.hitFlash>0){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,27,0,Math.PI*2);ctx.stroke();}
  if(car===cars[0]&&keys.has('shift')&&boost>0&&state==='playing'){ctx.fillStyle='#70ebff';ctx.shadowColor=BLUE;ctx.shadowBlur=18;ctx.beginPath();ctx.moveTo(-6,20);ctx.lineTo(0,31+Math.random()*8);ctx.lineTo(6,20);ctx.fill();ctx.shadowBlur=0;}
  // Role number insignia on AI cars.
  if(!car.human){ctx.fillStyle='#071522';ctx.font='bold 8px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(String(car.role+1),0,8);}
  ctx.restore();
}
function drawBall(now) {
  const y=ball.y-ball.z*.62,r=ball.r;
  ctx.save();ctx.globalAlpha=Math.max(.14,.36-ball.z/600);ctx.fillStyle='#020810';ctx.beginPath();ctx.ellipse(ball.x,ball.y+5,r*1.25+ball.z*.04,r*.62+ball.z*.025,0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.save();ctx.translate(ball.x,y);ctx.rotate(ball.spin);ctx.shadowColor='#d6f7ff';ctx.shadowBlur=ball.z>0?13:7;
  const g=ctx.createRadialGradient(-7,-9,2,0,0,r*1.25);g.addColorStop(0,'#ffffff');g.addColorStop(.28,'#edf6f7');g.addColorStop(.68,'#9fb5c0');g.addColorStop(1,'#384e5d');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
  ctx.strokeStyle='#425967';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r*.66,0,Math.PI*2);ctx.stroke();
  for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ctx.save();ctx.rotate(a);ctx.fillStyle=i%2?'#6c818d':'#344b59';ctx.beginPath();ctx.moveTo(0,-r*.91);ctx.lineTo(6,-r*.6);ctx.lineTo(3,-r*.34);ctx.lineTo(-4,-r*.38);ctx.lineTo(-6,-r*.68);ctx.closePath();ctx.fill();ctx.restore();}
